import { useState, useMemo, useEffect, type RefObject } from "react";

import { useIsomorphicLayoutEffect } from "./use-isomorphic-layout-effect";

const resolveContainer = (
  containerElement?: HTMLElement | RefObject<HTMLElement | null> | null,
): HTMLElement | null => {
  if (typeof document === "undefined") return null;

  if (containerElement instanceof HTMLElement) return containerElement;
  if (containerElement && "current" in containerElement && containerElement.current) {
    return containerElement.current;
  }

  const el = document.body.querySelector(`[data-textura-theme-provider="true"]`);
  return (el as HTMLElement) || document.body;
};

/**
 * Hook to resolve the portal container for overlays (Modal, Drawer).
 * It determines the target element to mount the portal into and checks if it is scoped.
 *
 * @param containerElement - The explicit container element or ref passed to the component.
 * @returns An object containing the resolved container element and a boolean indicating if it is scoped.
 */
export const usePortalContainer = (
  containerElement?: HTMLElement | RefObject<HTMLElement | null> | null,
) => {
  // Lazy init avoids the open-flash from first-paint mounting to document.body.
  const [resolvedContainer, setResolvedContainer] = useState<HTMLElement | null>(() =>
    resolveContainer(containerElement),
  );

  // Layout pass catches sibling refs; effect pass catches parent refs (which
  // attach after child layout effects).
  useIsomorphicLayoutEffect(() => {
    const next = resolveContainer(containerElement);
    setResolvedContainer((prev) => (prev === next ? prev : next));
  }, [containerElement]);

  useEffect(() => {
    const next = resolveContainer(containerElement);
    setResolvedContainer((prev) => (prev === next ? prev : next));
  }, [containerElement]);

  const isScoped = useMemo(() => {
    if (!containerElement || !resolvedContainer) return false;
    const containerEl =
      containerElement instanceof HTMLElement ? containerElement : containerElement.current;
    return resolvedContainer === containerEl;
  }, [containerElement, resolvedContainer]);

  return { resolvedContainer, isScoped };
};
